import { HttpClient, HttpErrorResponse } from '@angular/common/http';
import { Injectable } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import ConfigService from 'src/app/core/services/config/config.service';
import { ApiErrorResponse } from 'src/app/dto/errors/api_response_error.dto';
import { PlayerDTO, NewPlayerDTO } from 'src/app/dto/player/new_player.dto';
import {
  AuthMessageDTO,
  LoginResponseDTO,
  SignupRequestDTO,
} from 'src/app/dto/auth/auth.dto';
import { UserType } from 'src/app/dto/enum/user_type';

@Injectable({
  providedIn: 'root',
})
export class AuthService {
  private readonly _userInfoStorageKey = 'USER_INFO';
  constructor(
    private readonly _http: HttpClient,
    private readonly _config: ConfigService
  ) {}

  get isConnected(): boolean {
    const info = localStorage.getItem(this._userInfoStorageKey);
    return !!info;
  }

  async getLoginMessage(): Promise<{
    message: string;
    nonce: string;
    timestamp: number;
  }> {
    const httpRequest = this._http.get<AuthMessageDTO>(
      `${this._config.backendBaseUrl}/api/Auth/login`
    );

    return firstValueFrom<{
      message: string;
      nonce: string;
      timestamp: number;
    }>(httpRequest);
  }

  async getSignupMessage(): Promise<{
    message: string;
    nonce: string;
    timestamp: number;
  }> {
    const httpRequest = this._http.get<AuthMessageDTO>(
      `${this._config.backendBaseUrl}/api/Auth/signup`
    );

    return firstValueFrom<{
      message: string;
      nonce: string;
      timestamp: number;
    }>(httpRequest);
  }

  async createPlayer(
    player: NewPlayerDTO,
    auth: {
      nonce: string;
      message: string;
      timestamp: number;
      signature: string;
    }
  ) {
    try {
      const suffix = player.userType == UserType.GameOwner ? 'owner' : 'player';
      const { message, nonce, timestamp, signature } = auth;

      // 4. Enviar a assinatura ao backend para validação
      const postRequest = this._http.post<PlayerDTO>(
        `${this._config.backendBaseUrl}/api/Auth/signup/${suffix}`,
        {
          nonce,
          message,
          timestamp,
          signature,
          ...player,
        } as SignupRequestDTO<NewPlayerDTO>
      );

      const creationResponseData = await firstValueFrom(postRequest);

      return Promise.resolve({
        status: true,
        error: undefined,
        data: creationResponseData,
      });
    } catch (error) {
      const response = error as HttpErrorResponse;
      const apiResponse: ApiErrorResponse = response.error;
      return Promise.reject(apiResponse);
    }
  }

  async login(auth: {
    nonce: string;
    signer: string;
    message: string;
    timestamp: number;
    signature: string;
    userType: UserType;
  }): Promise<{
    error?: string;
    status: boolean;
    data?: LoginResponseDTO;
  }> {
    try {
      const { userType, signer, message, nonce, timestamp, signature } = auth;

      // 4. Enviar a assinatura ao backend para validação
      const postRequest = this._http.post<LoginResponseDTO>(
        `${this._config.backendBaseUrl}/api/Auth/login`,
        {
          nonce,
          message,
          userType,
          timestamp,
          signature,
          wallet: signer?.toUpperCase(),
        }
      );

      const loginResponseData = await firstValueFrom(postRequest);

      localStorage.setItem(
        this._userInfoStorageKey,
        JSON.stringify(loginResponseData)
      );

      return Promise.resolve({
        status: true,
        error: undefined,
        data: loginResponseData,
      });
    } catch (error) {
      const response = error as HttpErrorResponse;
      const apiResponse: ApiErrorResponse = response.error;
      return Promise.reject(apiResponse);
    }
  }
}
