import {
  Fragment,
  BaseContract,
  TransactionRequest,
  ContractTransactionResponse,
  Addressable,
  ContractRunner,
  Interface,
  InterfaceAbi,
  TransactionResponse,
} from 'ethers';

interface IContractMetaCall {
  getFragment: () => Fragment;
  staticCall: (...args: any[]) => Promise<any>;
  estimateGas: (...args: any[]) => Promise<bigint>;
  staticCallResult: (...args: any[]) => Promise<unknown>;
  send: () => Promise<ContractTransactionResponse>;
  populateTransaction: () => Promise<TransactionRequest>;
}

export class TokenFactoryContract extends BaseContract {
  constructor(
    target: string | Addressable,
    abi: Interface | InterfaceAbi,
    runner?: null | ContractRunner,
    _deployTx?: null | TransactionResponse
  ) {
    super(target, abi, runner, _deployTx);
  }

  create!: {
    _key: string;
    _contract: BaseContract;
    name: string;
    fragment: Fragment;
    (
      nonce: bigint | string,
      name: string,
      symbol: string,
      initialSupply: bigint | string,
      r: bigint | string,
      s: bigint | string,
      v: number,
      options?: TransactionRequest
    ): Promise<ContractTransactionResponse>;
  } & IContractMetaCall;

  nonces!: {
    _key: string;
    _contract: BaseContract;
    name: string;
    fragment: Fragment;
    (address: string, options?: TransactionRequest): Promise<any>;
  } & IContractMetaCall;

  getTokenAddress!: {
    _key: string;
    _contract: BaseContract;
    name: string;
    fragment: Fragment;
    (symbol: string, options?: TransactionRequest): Promise<bigint | string>;
  } & IContractMetaCall;

  isCreationSignatureValid!: {
    _key: string;
    _contract: BaseContract;
    name: string;
    fragment: Fragment;
    (
      nonce: bigint | string,
      name: string,
      symbol: string,
      initialSupply: bigint | string,
      r: bigint | string,
      s: bigint | string,
      v: number,
      options?: TransactionRequest
    ): Promise<boolean>;
  } & IContractMetaCall;
}
