import { Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { IAppConfig } from 'src/app/dto/config/app_config.dto';
import { TokenFactoryConfig } from 'src/app/dto/config/token_factory.dto';
import { environment } from 'src/environments/environment.development';

@Injectable({
  providedIn: 'root',
})
export default class ConfigService implements IAppConfig {
  private _config: IAppConfig;

  get gameTokenFactoryConfig(): TokenFactoryConfig | undefined {
    return this._config.gameTokenFactoryConfig;
  }

  get nodeBaseApiUrl(): string {
    return this._config.nodeBaseApiUrl;
  }

  get backendBaseUrl(): string {
    return this._config.backendBaseUrl;
  }

  constructor() {
    this._config = {
      ...environment,
      gameTokenFactoryConfig: undefined,
    };
  }

  async load(http: HttpClient): Promise<void> {
    // TODO: implementar o load das configs async se necessário
    return Promise.resolve();
    // try {
    //   this._config.gameTokenFactoryConfig =
    //     await this.loadTokenfactoryContractData(http);
    // } catch (e) {
    //   console.error(e);
    //   throw e;
    // }
  }

  private async loadTokenfactoryContractData(
    http: HttpClient
  ): Promise<TokenFactoryConfig> {
    return new Promise((resolve, reject) => {
      http
        .get<any>(
          `${this._config.nodeBaseApiUrl}/contract/GameTokenFactory/metadata`
        )
        .subscribe({
          next: (data) =>
            resolve({ abi: data.abi, address: data.contractAddress }),
          error: (error) => reject(error),
        });
    });
  }
}
