import { Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { BrowserProvider } from 'ethers';
import { Web3ProviderService } from 'src/app/core/services/web3/web3-provider.service';
import ConfigService from 'src/app/core/services/config/config.service';
import { firstValueFrom } from 'rxjs';
import {
  NewGameRequestDTO,
  NewGameResponseDTO,
} from 'src/app/dto/game/game.dto';

@Injectable()
export class GameService {
  constructor(private _http: HttpClient, private _config: ConfigService) {}

  async create(newGame: NewGameRequestDTO): Promise<NewGameResponseDTO> {
    const response = this._http.post<NewGameResponseDTO>(
      `${this._config.backendBaseUrl}/api/game`,
      newGame
    );

    return await firstValueFrom(response);
  }

  // TODO: remover após testes
  async getFakeGame(): Promise<NewGameResponseDTO> {
    const response = this._http.get<NewGameResponseDTO>(
      `${this._config.backendBaseUrl}/api/test/game/new`
    );

    return await firstValueFrom(response);
  }
}
