import { ethers } from 'ethers';
import { Injectable } from '@angular/core';
import { BrowserProvider, JsonRpcSigner } from 'ethers';
import { EIP712Data } from 'src/app/dto/signature/eip712_data.dto';
import { Router } from '@angular/router';

// o primeiro argumento do send, pode ser consultado aqui
// EIP-1193: https://eips.ethereum.org/EIPS/eip-1193

@Injectable({
  providedIn: 'root',
})
export class Web3ProviderService {
  private _provider: BrowserProvider | null = null;
  private readonly _accounts: string[] = [];
  private _isAvailable: boolean = false;

  constructor(private router: Router) {
    this._isAvailable = window.ethereum !== undefined;

    if (this._isAvailable) {
      this._provider = new BrowserProvider(window.ethereum);

      // Ouvir mudanças de conta (TODO: tipar)
      window.ethereum.on('accountsChanged', (accounts: any) => {
        debugger;
        this._accounts.length = 0;
        this._accounts.push(...accounts);
        // Emitir evento se necessário
      });
    }
  }

  get available(): boolean {
    return this._isAvailable;
  }

  get connected(): boolean {
    return this._accounts.length > 0;
  }

  getSigner() {
    return this._provider!.getSigner();
  }

  send(command: string, args: []) {
    return this._provider!.send(command, args);
  }

  async chainId(): Promise<number> {
    if (!this._isAvailable || !this._provider) {
      this.handleNoProvider();
      return Promise.reject(new Error('Web3 provider not available'));
    }

    const chainId = (await this._provider.getNetwork()).chainId;
    return Promise.resolve(Number(chainId));
  }

  async currentAccount(): Promise<JsonRpcSigner> {
    if (!this._isAvailable || !this._provider) {
      this.handleNoProvider();
      return Promise.reject(new Error('Web3 provider not available'));
    }

    return this._provider.getSigner();
  }

  async connect(): Promise<Array<string>> {
    if (!this._isAvailable || !this._provider) {
      this.handleNoProvider();
      return Promise.reject(new Error('Web3 provider not available'));
    }

    return this._provider
      .send('eth_requestAccounts', [])
      .then((accounts: Array<string>) => {
        this._accounts.length = 0;
        this._accounts.push(...(accounts || []));
        return accounts;
      })
      .catch((err) => {
        console.error('Wallet not available', err);
        throw err;
      });
  }

  async signTypedData_v4(eip721Data: EIP712Data): Promise<string> {
    if (!this._isAvailable || !this._provider) {
      this.handleNoProvider();
      return Promise.reject(new Error('Web3 provider not available'));
    }

    try {
      const signer = await this._provider.getSigner();

      const signature: string = await this._provider.send(
        'eth_signTypedData_v4',
        [signer.address, eip721Data]
      );

      return signature as string;
    } catch (e) {
      console.error(e);
      return Promise.reject(e);
    }
  }

  async signPersonal(message: string): Promise<string> {
    if (!this._isAvailable || !this._provider) {
      this.handleNoProvider();
      return Promise.reject(new Error('Web3 provider not available'));
    }

    try {
      const signer = await this._provider.getSigner();

      // Converte a string em bytes e depois para hexadecimal
      const hexMessage = ethers.hexlify(ethers.toUtf8Bytes(message));

      const signature: string = await this._provider.send('personal_sign', [
        hexMessage,
        signer.address,
      ]);

      return signature;
    } catch (e) {
      console.error(e);
      return Promise.reject(e);
    }
  }

  private handleNoProvider(): void {
    // Navega para a página de erro ou mostra uma mensagem
    this.router.navigate(['/no-web3-provider']);
  }
}
