import { HttpClient } from '@angular/common/http';
import { Component, OnDestroy, OnInit } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import ConfigService from 'src/app/core/services/config/config.service';

@Component({
  selector: 'app-provider-account',
  //standalone: true,
  //imports: [],
  templateUrl: './provider-account.component.html',
  styleUrl: './provider-account.component.scss',
})
export class ProviderAccountComponent implements OnInit, OnDestroy {
  accounts: any[] = [];

  constructor(
    private _config: ConfigService,
    private _httpClient: HttpClient
  ) {}

  ngOnInit(): void {
    window.addEventListener(
      'message',
      this.handleAuthResponse.bind(this),
      false
    );
  }

  ngOnDestroy(): void {
    window.removeEventListener('message', this.handleAuthResponse.bind(this));
  }

  async steamLogin(): Promise<any> {
    const windowFeatures =
      'width=600,height=700,resizable=yes,scrollbars=yes,status=yes';

    const url = `${this._config.backendBaseUrl}/api/auth/steam`;
    const popup = window.open(url, 'steamWindow', windowFeatures)!;
    if (!popup) {
      // TODO: usar toastr ou algo assim
      alert('O popup foi bloqueado. Por favor, permita popups para este site.');
      return;
    }
  }

  async psnLogin(): Promise<any> {}

  async xboxLogin(): Promise<any> {
    const windowFeatures =
      'width=600,height=700,resizable=yes,scrollbars=yes,status=yes';

    const url = `${this._config.backendBaseUrl}/api/auth/xbox`;
    const popup = window.open(url, 'steamWindow', windowFeatures)!;
    if (!popup) {
      // TODO: usar toastr ou algo assim
      alert('O popup foi bloqueado. Por favor, permita popups para este site.');
      return;
    }
  }

  async googleLogin(): Promise<any> {}

  async handleAuthResponse(evt: any) {
    // console.log(evt);
    const { success, name, payload, provider } = evt.data;
    if (name !== '3rd_auth') return;

    if (!success) {
      // TODO: mostrar algum alerta (toastr sei la)
      alert(payload);
    }

    switch (provider) {
      case 'steam':
        await this.handleSteamAuthResponse(payload);
        break;
      default:
        break;
    }
  }

  async handleSteamAuthResponse(payload: any) {
    const { avatar, profileUrl, personaName, steamId } = payload;
    this.accounts.push({
      avatar,
      provider: 'steam',
      profile: profileUrl,
      providerId: steamId,
      username: personaName,
    });
  }
}
