import { NgModule } from '@angular/core';
import { RouterModule, Routes } from '@angular/router';
import { LoginPageComponent } from './features/auth/pages/login/login.component';
import { NewGameComponent } from './features/new-game/pages/new-game.component';
import { SignupPageComponent } from './features/auth/pages/signup/signup.component';
import { LandingPageComponent } from './features/landing-page/pages/landing-page.component';
import { LoggedInStructureComponent } from './core/components/logged-in-layout/logged-in-structure/structure.component';
import { LoggedOutStructureComponent } from './core/components/logged-out-layout/logged-out-structure/structure.component';
import { ProviderAccountComponent } from './features/provider-account/pages/provider-account.component';
import { NoWeb3ProviderComponent } from './features/no-web3-provider/no-web3-provider.component';

const loggedOutRoutes: Routes = [
  {
    path: '',
    component: LoggedOutStructureComponent,
    children: [
      { path: '', component: LandingPageComponent },
      { path: 'signup', component: SignupPageComponent },
      { path: 'login', component: LoginPageComponent },
      { path: 'no-web3-provider', component: NoWeb3ProviderComponent },
    ],
  },
];

const loggedInRoutes: Routes = [
  {
    path: '',
    component: LoggedInStructureComponent,
    children: [
      {
        path: 'new-game', // TODO: seria melhor game/new?
        component: NewGameComponent,
        loadChildren: () =>
          import('./features/new-game/new-game.module').then(
            (m) => m.NewGameModule
          ),
      },
      {
        path: 'accounts',
        component: ProviderAccountComponent,
        loadChildren: () =>
          import('./features/provider-account/provider-account.module').then(
            (m) => m.ProviderAccountModule
          ),
      },
    ],
  },
];

const routes: Routes = [
  // Rotas para áreas não autenticadas
  ...loggedOutRoutes,

  // Rotas para áreas autenticadas
  ...loggedInRoutes,

  // Redirecionar a rota raiz para a área não autenticada
  // { path: '', redirectTo: 'a', pathMatch: 'full' },

  // Redirecionar qualquer rota não encontrada para a área não autenticada
  // { path: '**', redirectTo: 'a' },
];

@NgModule({
  imports: [RouterModule.forRoot(routes)],
  exports: [RouterModule],
})
export class AppRoutingModule {}
