import { Component, inject } from '@angular/core';
import { Router } from '@angular/router';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { ApiErrorResponse } from 'src/app/dto/errors/api_response_error.dto';
import { AuthService } from 'src/app/core/services/auth/auth.service';
import { Web3ProviderService } from 'src/app/core/services/web3/web3-provider.service';

// https://material.angular.io/components/snack-bar/overview
import {
  MatSnackBar,
  MatSnackBarAction,
  MatSnackBarActions,
  MatSnackBarLabel,
  MatSnackBarRef,
} from '@angular/material/snack-bar';
import { UserType } from 'src/app/dto/enum/user_type';

@Component({
  selector: 'app-login-page',
  templateUrl: './login.component.html',
  styleUrls: ['./login.component.scss'],
})
export class LoginPageComponent {
  loginForm!: FormGroup;
  loginError?: string;
  //private _snackBar = inject(MatSnackBar);

  get walletConnected(): boolean {
    return !!this.loginForm.controls['wallet'].value;
  }

  // get walletFieldErrors() {
  //   return this.loginForm.controls['wallet'].errors;
  // }

  constructor(
    private fb: FormBuilder,
    private readonly _router: Router,
    private readonly _snackBar: MatSnackBar,
    private readonly _authService: AuthService,
    private readonly _web3Provider: Web3ProviderService
  ) {
    this.loginForm = this.fb.group({
      wallet: ['', [Validators.required]],
      profile: ['', [Validators.required]],
    });
  }

  ngOnInit() {}

  openSnackBar(message: string) {
    // this._snackBar.openFromComponent(PizzaPartyAnnotatedComponent, {
    //   duration: this.durationInSeconds * 1000,
    // });

    this._snackBar.open(message, undefined, {
      duration: 3000,
    });
  }

  async connectWallet(event: any): Promise<void> {
    try {
      const accounts = await this._web3Provider.connect();
      this.loginForm.controls['wallet'].setValue(accounts[0]?.toUpperCase());
    } catch (error: any) {
      console.error('Wallet connection error:', error);
    }
  }

  async onSubmit(): Promise<void> {
    const userType: UserType = this.loginForm.controls['profile'].value;
    const { message, nonce, timestamp } =
      await this._authService.getLoginMessage();

    const signer = await this._web3Provider.currentAccount();
    const signature = await this._web3Provider.signPersonal(message);

    this._authService
      .login({
        userType,
        message: message,
        nonce: nonce,
        signer: signer.address,
        timestamp: timestamp,
        signature: signature,
      })
      .then((r) => {
        this._router.navigate(['new-game']);
      })
      .catch(({ message, detail }: ApiErrorResponse) => {
        this.loginError = message;
        const m = message + detail.map((d) => d + '\n');
        console.error(m);

        // Adiciona o erro ao controle
        // this.loginForm.controls['wallet'].setErrors({
        //   ...this.walletFieldErrors,
        //   unauthorized: message,
        // });
      });
  }

  showAlert(msg: string) {
    // usar algum component angular, tipo Toaster
    alert(msg);
  }
}
