import { APP_INITIALIZER, NgModule } from '@angular/core';
import { AppComponent } from './app.component';
import { AppCoreModule } from './core/core.module';
import { RouterModule } from '@angular/router';
import { BrowserModule, DomSanitizer } from '@angular/platform-browser';
import { AppRoutingModule } from './app.routing.module';
import { CommonModule } from '@angular/common';
import { AuthModule } from './features/auth/auth.module';
import { LandingPageModule } from './features/landing-page/landing-page.module';
import { BrowserAnimationsModule } from '@angular/platform-browser/animations';
import { appInitializer } from './initializers/app.initializer';
import { MatIconRegistry } from '@angular/material/icon';
import { NewGameModule } from './features/new-game/new-game.module';

@NgModule({
  providers: [appInitializer],
  bootstrap: [AppComponent],
  declarations: [AppComponent],
  imports: [
    CommonModule,
    BrowserModule,
    RouterModule,

    // core module
    AppCoreModule,

    // routes
    AppRoutingModule,

    // features
    AuthModule,
    NewGameModule,
    LandingPageModule,
    BrowserAnimationsModule,
  ],
})
export class AppModule {
  constructor(matIconRegistry: MatIconRegistry, domSanitizer: DomSanitizer) {
    const svgs: { [key: string]: string } = {
      psn: 'assets/icons/psn.svg',
      logo: 'assets/icons/logo.svg',
      xbox: 'assets/icons/xbox.svg',
      steam: 'assets/icons/steam.svg',
      google: 'assets/icons/google.svg',
      metamask: 'assets/icons/metamask.svg',
    };

    for (const key in svgs) {
      matIconRegistry.addSvgIcon(
        key,
        domSanitizer.bypassSecurityTrustResourceUrl(svgs[key])
      );
    }
  }
}
