  private checkMetamaskInstallation(): boolean {
    if ((window as any).ethereum == undefined) {
      // TODO: talvez um toastr ou redirecionar para outra pagina
      alert('Metamask wallet is not installed');
      return false;
    }

    return true;
  }

  // TODO:
