  // MetamaskService talvez
  async connect() {
    try {
      if (!this.checkMetamaskInstallation()) {
        console.error('MetaMask não detectado.');
      }

      // talvez nao precise

      // as duas formas funcionam
      const accounts = await this._provider.send('eth_requestAccounts', []);
      // const accounts = await this.provider.listAccounts(); assim retorna JsonRPCSigner

      return accounts;
    } catch (e) {
      console.error(e);
      throw e;
    }
  }

  async deployToken(data: {
    to: string;
    name: string;
    owner: string;
    nonce: string;
    symbol: string;
    decimals: number;
    contractABI: string;
    initialSupply: string;
    signature: SignatureDTO;
    contractAddress: string;
  }): Promise<string> {
    return new Promise(async (resolve, reject) => {
      try {
        debugger;
        //TODO: talvez, antes de enviar para o blockchain, devemos validar os parametros com nosso back,
        // ele deve checar se ja existe o token por exemplo;
        const {
          to,
          name,
          owner,
          nonce,
          symbol,
          decimals,
          signature,
          contractABI,
          initialSupply,
          contractAddress,
        } = data;

        // sera que o nonce precisa ser assim?
        // const bigNonce = BigInt(nonce);
        const supply = parseUnits(initialSupply, decimals);
        const signer = await this._provider.getSigner();
        const contract = new TokenFactoryContract(
          contractAddress,
          contractABI,
          signer
        );

        // https://docs.ethers.org/v6/api/utils/events/
        // TODO: ta emitindo aparentemente mais de uma vez
        contract!.on('SucceededDeploy', (creator, newTokenAddress) => {
          console.log(
            `Token criado por '${creator}' com sucesso em '${newTokenAddress}'`
          );
          resolve(newTokenAddress);
        });

        contract!.on('FailedDeploy', (creator, reason) => {
          console.log(`Falha ao criar token por '${creator}': ${reason}`);
          reject(reason);
        });

        const estimatedGas = await contract.create.estimateGas(
          nonce,
          name,
          symbol,
          supply,
          signature.r,
          signature.s,
          signature.v
        );

        const tx = await contract.create(
          nonce,
          name,
          symbol,
          supply,
          signature.r,
          signature.s,
          signature.v,
          {
            gasLimit: estimatedGas,
          }
        );

        // TODO: nao sei para que usar o resultado
        await tx.wait();
      } catch (error) {
        // TODO: nao sei se tem um jeito de mostrar um erro amigavel
        debugger;
        console.error('Erro ao deployar o token:', error);
        return reject(error);
      }
    });
  }

